-- PREMIUM APPLE ECOSYSTEM ACCESSORIES (10 products)
('apple-airtag-4-pack', 'Apple AirTag 4-Pack Item Tracker Bundle - Precision Finding 2.0', 'accessories', 85000, 82900, 68000, 25, 0.04, '/assets/products/airtag-4pack.jpg', 'Never lose your essentials again with Apple''s upgraded tracker featuring second-generation Ultra Wideband chip with Precision Finding 2.0 that guides you to your item with exact distance and direction. Four-pack covers keys, wallet, luggage, and backpack.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/airtag-4pack.jpg', 78000, 4.8, 1, 'Apple', 1, 1),

('apple-magsafe-wallet-stand', 'Apple FineWoven MagSafe Wallet with Built-in Kickstand - Taupe', 'accessories', 55000, 53900, 45000, 20, 0.06, '/assets/products/magsafe-wallet-stand.jpg', 'Premium FineWoven material now made from 68% post-consumer recycled fibers. This MagSafe wallet holds three cards with RFID protection and features a hidden, micro-articulated aluminum kickstand for hands-free viewing in both portrait and landscape.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/magsafe-wallet-stand.jpg', 50500, 4.6, 1, 'Apple', 1, 1),

('belkin-continuity-camera-mount', 'Belkin Continuity Camera Mount for MacBook Pro with MagSafe', 'accessories', 35000, 33900, 28500, 15, 0.11, '/assets/products/belkin-continuity-mount.jpg', 'Transform your iPhone into the world''s best webcam with a single magnetic click. This Apple-certified mount attaches securely to your MacBook''s lid, perfectly aligning your iPhone''s pro camera system for Center Stage, Studio Light, and Desk View in video calls.', 1, unixepoch('2026-06-16'), 1, 28500, '/assets/products/belkin-continuity-mount.jpg', 31800, 4.7, 1, 'Belkin', 1, 1),

('otterbox-defender-xt-magsafe', 'OtterBox Defender XT MagSafe Case for iPhone 16 Pro - Black Crystal', 'accessories', 45000, 43900, 36500, 25, 0.07, '/assets/products/otterbox-defender-xt.jpg', 'OtterBox legendary protection now optimized for MagSafe. The Defender XT features 5x military-grade drop protection, port covers that block dust, and a textured grip that prevents drops. MagSafe magnets align perfectly every time.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/otterbox-defender-xt.jpg', 41500, 4.7, 1, 'OtterBox', 1, 1),

('twelve-south-hirise-pro', 'Twelve South HiRise Pro Adjustable MacBook Stand - Space Grey', 'accessories', 85000, 82900, 68000, 10, 1.45, '/assets/products/twelve-south-hirise-pro.jpg', 'Elevate your MacBook to the perfect ergonomic height with this precision-machined aluminum stand. The ventilated pillar design improves airflow for cooler operation, while the padded cradle and non-slip base keep your laptop secure at any angle.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/twelve-south-hirise-pro.jpg', 78000, 4.7, 0, 'Twelve South', 1, 1),

('anker-maggo-charging-station', 'Anker MagGo 3-in-1 Charging Station Qi2 for iPhone/Watch/AirPods', 'chargers', 85000, 82900, 68000, 15, 0.52, '/assets/products/anker-maggo-3in1.jpg', 'The ultimate Apple travel companion folds flat to pocket size. Qi2-certified 15W magnetic charging for iPhone, fast Apple Watch charging, and a dedicated AirPods spot power your entire ecosystem from one compact charger with a 5ft cable.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/anker-maggo-3in1.jpg', 78000, 4.7, 1, 'Anker', 1, 1),

('nomad-stand-one-max-qi2', 'Nomad Stand One Max Qi2 3-in-1 Wireless Charger - Carbide Black', 'chargers', 145000, 139000, 118000, 8, 1.35, '/assets/products/nomad-stand-one-max.jpg', 'A sculptural statement in solid metal and glass. This premium 3-in-1 charger features official Qi2 15W MagSafe, fast Apple Watch charging, and an AirPods pad, all mounted on a weighted base with a single, undetectable braided cable for a cable-free aesthetic.', 1, unixepoch('2026-06-16'), 1, 118000, '/assets/products/nomad-stand-one-max.jpg', 132000, 4.8, 0, 'Nomad', 1, 1),

('mophie-3in1-travel-magsafe', 'Mophie 3-in-1 Travel Charger with MagSafe - Black Fabric', 'chargers', 95000, 92900, 78000, 12, 0.48, '/assets/products/mophie-3in1-travel.jpg', 'A complete Apple charging kit that packs into a compact travel case. The MagSafe pad charges iPhone at 25W, the Apple Watch puck snaps up for Nightstand mode, and the AirPods spot completes the trio. Includes a 45W GaN wall adapter.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/mophie-3in1-travel.jpg', 88000, 4.6, 1, 'Mophie', 1, 1),

('elago-magsafe-stand-hub', 'elago MagSafe Stand Hub with USB-C 7-in-1 Docking Station', 'accessories', 65000, 63900, 52000, 10, 0.55, '/assets/products/elago-magsafe-hub.jpg', 'One elegant aluminum stand replaces your MacBook dongle collection. The MagSafe charger holds your iPhone at the perfect viewing angle while the integrated hub provides HDMI, USB-A, SD card, and 100W PD passthrough for your laptop.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/elago-magsafe-hub.jpg', 59000, 4.5, 0, 'elago', 1, 1),

('caudabe-sheath-magsafe-case', 'Caudabe Sheath MagSafe Case for iPhone 16 Pro Max - Navy Blue', 'accessories', 25000, 23900, 19500, 20, 0.04, '/assets/products/caudabe-sheath.jpg', 'The thinnest case that still offers genuine drop protection. At just 0.9mm thin, the Sheath maintains your iPhone''s original form factor while its ShockLite polymer absorbs impact. The texture-fused finish resists fingerprints and provides a secure grip.', 1, unixepoch('2026-06-16'), 1, 19500, '/assets/products/caudabe-sheath.jpg', 22500, 4.6, 1, 'Caudabe', 1, 1),

-- FITNESS & WELLNESS EQUIPMENT (10 products)
('peloton-bike-plus-2', 'Peloton Bike+ 2 Connected Exercise Bike with Auto-Resistance', 'fitness', 1250000, 1215000, 1050000, 3, 64.0, '/assets/products/peloton-bike-plus-2.jpg', 'The world''s most immersive home fitness experience gets a complete redesign. The 27-inch rotating touchscreen, auto-resistance that follows your instructor''s cues, and Apple Watch integration make every class feel like a private studio session.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/peloton-bike-plus-2.jpg', 1150000, 4.8, 1, 'Peloton', 1, 1),

('bowflex-selecttech-560-dumbbells', 'Bowflex SelectTech 560 Adjustable Dumbbells with Bluetooth - Pair', 'fitness', 480000, 469000, 410000, 4, 38.0, '/assets/products/bowflex-560.jpg', 'Replace 30 individual dumbbells with one intelligent pair. Adjust weight from 5 to 60 pounds with a turn of the dial, while the Bluetooth-connected 3DT sensors track your reps, sets, and form in real-time via the Bowflex SelectTech app.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/bowflex-560.jpg', 438000, 4.7, 0, 'Bowflex', 1, 1),

('schwinn-ic4-indoor-cycle', 'Schwinn IC4 Indoor Cycling Bike with JRNY App Compatibility', 'fitness', 480000, 469000, 410000, 5, 48.5, '/assets/products/schwinn-ic4.jpg', 'A studio-quality indoor cycle compatible with Peloton, Zwift, and JRNY apps via Bluetooth FTMS. The magnetic resistance system operates silently, while the dual water bottle holders, tablet mount, and 40lb flywheel deliver a premium riding experience.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/schwinn-ic4.jpg', 438000, 4.6, 0, 'Schwinn', 1, 1),

('theragun-relief-pro', 'Theragun Relief Pro Percussive Massage Gun with Heat & Cold', 'fitness', 280000, 275000, 235000, 8, 1.15, '/assets/products/theragun-relief-pro.jpg', 'Professional recovery with interchangeable heat and cold attachments. The Relief Pro combines Theragun''s signature 16mm amplitude percussion with soothing heat up to 113°F or cold therapy, accelerating muscle recovery and reducing soreness after intense workouts.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/theragun-relief-pro.jpg', 258000, 4.7, 1, 'Therabody', 1, 1),

('manduka-pro-yoga-mat-6mm', 'Manduka PRO Yoga Mat 6mm with Lifetime Warranty - Black Magic', 'fitness', 85000, 82900, 68000, 10, 3.4, '/assets/products/manduka-pro.jpg', 'The last yoga mat you''ll ever buy, guaranteed for life. The 6mm dense cushion protects your joints without compromising stability, while the closed-cell surface repels moisture and bacteria. Trusted by yoga teachers worldwide for over 25 years.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/manduka-pro.jpg', 78000, 4.8, 0, 'Manduka', 1, 1),

('hyperice-venom-3-back', 'Hyperice Venom 3 Back Wearable Heat & Vibration Wrap', 'fitness', 220000, 215000, 178000, 6, 1.25, '/assets/products/hyperice-venom-3.jpg', 'Unknot your back in minutes. The Venom 3 wraps around your lower back with three customizable heat zones and HyperSync vibration pods that target sore muscles. Bluetooth app control lets you dial in the exact intensity for relief after long workdays.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/hyperice-venom-3.jpg', 205000, 4.5, 0, 'Hyperice', 1, 1),

('renpho-smart-jump-rope', 'RENPHO Smart Jump Rope 2.0 with App & Calorie Tracking - Black', 'fitness', 12500, 11900, 9500, 30, 0.28, '/assets/products/renpho-jump-rope.jpg', 'Track every skip with precision. The app-connected handle counts jumps, calculates calories, and monitors workout duration in real-time. The adjustable steel rope with ball bearings spins smoothly, while the weighted handles add upper body engagement.', 1, unixepoch('2026-06-16'), 1, 9500, '/assets/products/renpho-jump-rope.jpg', 11200, 4.5, 1, 'RENPHO', 1, 1),

('trx-pro5-suspension-trainer', 'TRX PRO5 Suspension Trainer System with Wall Mount - Commercial Grade', 'fitness', 185000, 179000, 148000, 8, 2.15, '/assets/products/trx-pro5.jpg', 'A complete gym that fits in a bag. The PRO5 is the latest evolution of the suspension training system used by professional athletes and military forces. The locking carabiner design, rubber handles, and door anchor enable hundreds of bodyweight exercises anywhere.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/trx-pro5.jpg', 168000, 4.7, 1, 'TRX', 1, 1),

('hydrow-wave-rowing-machine', 'Hydrow Wave Connected Rowing Machine with 16" Display - Black', 'fitness', 850000, 829000, 720000, 3, 49.0, '/assets/products/hydrow-wave.jpg', 'Row on the world''s most beautiful waterways from your living room. The Wave''s electromagnetic drag simulates real water resistance, while the 16-inch display transports you to live and on-demand rowing sessions led by world-class athletes in stunning locations.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/hydrow-wave.jpg', 780000, 4.6, 0, 'Hydrow', 1, 1),

('nordictrack-vault-complete', 'NordicTrack Vault Complete Smart Home Gym with Mirror Display', 'fitness', 1450000, 1420000, 1250000, 2, 68.0, '/assets/products/nordictrack-vault.jpg', 'A full gym disguised as a full-length mirror. The Vault Complete stores dumbbells, kettlebells, resistance bands, and a yoga mat behind a reflective 61-inch display that streams iFIT workouts with AI-powered form correction and personal training.', 1, unixepoch('2026-06-16'), 1, 1250000, '/assets/products/nordictrack-vault.jpg', 1350000, 4.5, 0, 'NordicTrack', 1, 1),

