('typhur-dome-air-fryer', 'Typhur Dome 10L Smart Air Fryer with Dual Heating Elements - Black', 'appliances', 185000, 179000, 148000, 8, 7.5, '/assets/products/typhur-dome.jpg', 'The air fryer that self-cleans with steam in 15 minutes. Dual heating elements with TenderCrisp technology cook food perfectly without shaking, while the clear glass dome lets you watch your food transform. The 10L capacity handles a whole chicken effortlessly.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/typhur-dome.jpg', 168000, 4.6, 1, 'Typhur', 1, 1),

('anova-precision-oven-2', 'Anova Precision Oven 2.0 Combi-Steam Smart Oven with Probe', 'appliances', 580000, 569000, 495000, 4, 15.0, '/assets/products/anova-oven-2.jpg', 'Sous vide, steam, bake, and air fry in one countertop appliance. The Precision Oven 2.0 uses wet and dry heat with a multi-point food probe to achieve restaurant-quality results automatically. WiFi-connected with thousands of guided recipes.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/anova-oven-2.jpg', 535000, 4.7, 0, 'Anova', 1, 1),

('meater-3-plus-thermometer', 'MEATER 3 Plus Wireless Smart Meat Thermometer with WiFi Range Extender', 'appliances', 85000, 82900, 68000, 15, 0.18, '/assets/products/meater-3-plus.jpg', 'Wirelessly monitor your food from up to 500 meters away with the new WiFi range extender. The MEATER 3 Plus features dual sensors that track internal meat temperature and ambient oven heat, with an advanced algorithm that predicts resting time for perfect results.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/meater-3-plus.jpg', 78000, 4.7, 1, 'MEATER', 1, 1),

