('kitchenaid-artisan-stand-mixer-pro', 'KitchenAid Artisan Stand Mixer 5.5L with Pouring Shield - Empire Red', 'appliances', 380000, 369000, 315000, 6, 13.0, '/assets/products/kitchenaid-artisan-red.jpg', 'The iconic kitchen companion that lasts generations. The 5.5L stainless steel bowl, 10 optimized speeds, and planetary mixing action handle everything from delicate meringues to heavy bread dough. Compatible with over 20 optional attachments.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/kitchenaid-artisan-red.jpg', 348000, 4.8, 1, 'KitchenAid', 1, 1),

('breville-smart-oven-air-fryer-pro', 'Breville Smart Oven Air Fryer Pro 36L with Element IQ - Brushed Steel', 'appliances', 380000, 369000, 315000, 5, 12.5, '/assets/products/breville-smart-oven.jpg', 'Thirteen cooking functions in one compact oven. Element IQ technology intelligently adjusts the power of six heating elements for precise cooking, while the super convection setting reduces cooking time by 30%. The 36L capacity fits a 5.5kg chicken.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/breville-smart-oven.jpg', 348000, 4.7, 1, 'Breville', 1, 1),

('whynter-ice-cream-maker-compressor', 'Whynter ICM-255LSY Stainless Steel Compressor Ice Cream Maker 2.5L', 'appliances', 220000, 215000, 178000, 5, 14.0, '/assets/products/whynter-ice-cream.jpg', 'No pre-freezing required—built-in compressor freezes while it churns for continuous batches of creamy gelato, sorbet, and frozen yogurt. The stainless steel housing, BPA-free aluminum bowl, and 2.5L capacity make this the choice of dessert enthusiasts.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/whynter-ice-cream.jpg', 205000, 4.5, 0, 'Whynter', 1, 1),

('sage-barista-touch-impress', 'Sage Barista Touch Impress Bean-to-Cup Espresso Machine - Black Truffle', 'appliances', 950000, 929000, 810000, 3, 11.5, '/assets/products/sage-barista-touch.jpg', 'Professional barista quality with an intuitive touchscreen that walks you through every step. The Impress Puck System auto-corrects dosing and tamping, while the ThermoJet heating reaches optimal temperature in 3 seconds. Built-in conical burr grinder with 30 settings.', 1, unixepoch('2026-06-16'), 1, 810000, '/assets/products/sage-barista-touch.jpg', 880000, 4.8, 0, 'Sage', 1, 1),

('zwilling-enfinigy-kitchen-scale', 'ZWILLING Enfinigy Smart Kitchen Scale with App & Nutrition Tracking', 'appliances', 45000, 43900, 36500, 12, 0.75, '/assets/products/zwilling-scale.jpg', 'German precision meets smart connectivity. The tempered glass scale weighs up to 10kg in 0.1g increments, while the ZWILLING Culinary World app provides step-by-step recipes and automatically calculates nutritional information as you weigh each ingredient.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/zwilling-scale.jpg', 41500, 4.6, 0, 'ZWILLING', 1, 1),

('oxo-good-grips-coffee-maker', 'OXO Good Grips 9-Cup Programmable Coffee Maker with Rainmaker Shower', 'appliances', 125000, 119000, 98000, 8, 4.8, '/assets/products/oxo-coffee-maker.jpg', 'SCA-certified Gold Cup brewing at home. The Rainmaker shower head evenly saturates grounds for optimal extraction, while the double-wall vacuum-insulated carafe keeps coffee hot for hours without a heating plate that burns it. Programmable up to 24 hours ahead.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/oxo-coffee-maker.jpg', 112000, 4.5, 1, 'OXO', 1, 1),

-- SMART LIGHTING SOLUTIONS (10 products)
('govee-glide-hexagon-pro', 'Govee Glide Hexagon Pro 3D Wall Light Panels 25-Piece Kit', 'smart-lighting', 250000, 245000, 215000, 6, 3.8, '/assets/products/govee-hexagon-pro.jpg', 'Create stunning 3D wall art that reacts to your music and games. These hexagon panels feature RGBIC+ technology for per-pixel color control, a built-in microphone for music sync, and HDMI DreamView that extends your screen colors across your entire wall.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/govee-hexagon-pro.jpg', 235000, 4.6, 1, 'Govee', 1, 1),

('twinkly-strings-gen-3', 'Twinkly Strings Gen 3 600-LED Smart Christmas Lights with Mapping', 'smart-lighting', 125000, 119000, 98000, 8, 1.15, '/assets/products/twinkly-strings-3.jpg', 'Year-round customizable lighting that maps each LED''s position. Point your phone camera at the lights and the app creates a 3D map, letting you design animations, gradients, and effects that flow perfectly across any space. IP65 rated for indoor and outdoor use.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/twinkly-strings-3.jpg', 112000, 4.6, 0, 'Twinkly', 1, 1),

