('philips-hue-infuse-ceiling', 'Philips Hue Infuse Large Ceiling Light 53W RGBW - White', 'smart-lighting', 185000, 179000, 148000, 5, 2.8, '/assets/products/hue-infuse-ceiling.jpg', 'A statement ceiling light that transforms any room''s atmosphere. The ultra-slim design emits 4,500 lumens of tunable white and 16 million colors, with the included Hue Bridge unlocking automations, sunrise wake-up routines, and entertainment sync with your TV.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/hue-infuse-ceiling.jpg', 168000, 4.7, 1, 'Philips', 1, 1),

('lifx-supercolor-br30-4pack', 'LIFX SuperColor BR30 1100-Lumen Smart Floodlight 4-Pack', 'smart-lighting', 65000, 63900, 52000, 12, 0.85, '/assets/products/lifx-br30-4pack.jpg', 'No hub required—these WiFi-connected floodlights deliver 1100 lumens each with LIFX''s widest color range. The 4-pack covers your kitchen or living room with vibrant colors and Polychrome technology that blends multiple colors on a single bulb.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/lifx-br30-4pack.jpg', 59000, 4.5, 0, 'LIFX', 1, 1),

('govee-permanent-outdoor-lights-pro', 'Govee Permanent Outdoor Lights Pro 150ft RGBIC with Matter', 'smart-lighting', 320000, 315000, 268000, 4, 4.5, '/assets/products/govee-outdoor-pro.jpg', 'Permanently install smart architectural lighting on your home''s eaves. The 150ft kit covers an average Nigerian house with individually addressable LEDs, Matter compatibility for any platform, and AI-powered scene creation that syncs to holidays and events.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/govee-outdoor-pro.jpg', 298000, 4.6, 1, 'Govee', 1, 1),

('yeelight-monitor-light-bar-pro', 'Yeelight Monitor Light Bar Pro RGBIC with Wireless Remote', 'smart-lighting', 45000, 43900, 36500, 15, 0.55, '/assets/products/yeelight-bar-pro.jpg', 'Professional asymmetric lighting eliminates screen glare while illuminating your desk. The RGBIC backlight adds ambient glow to your setup, with a wireless dimmer puck and smart home integration via Matter. 45° angled optics put light exactly where you need it.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/yeelight-bar-pro.jpg', 41500, 4.6, 1, 'Yeelight', 1, 1),

('wiz-matter-smart-plug-light', 'WiZ Matter Smart Plug with Night Light - 2-Pack', 'smart-lighting', 22000, 21500, 17500, 20, 0.18, '/assets/products/wiz-smart-plug.jpg', 'Make any lamp smart and add a gentle night light. This Matter-compatible smart plug features a built-in, dimmable warm LED ring that guides you in the dark, while the plug controls lamps, fans, or holiday decorations with scheduling and voice control.', 1, unixepoch('2026-06-16'), 1, 17500, '/assets/products/wiz-smart-plug.jpg', 20500, 4.4, 0, 'WiZ', 1, 1),

('elgato-key-light-air-mk2', 'Elgato Key Light Air Mk.2 Professional Edge-Lit LED Panel - White', 'smart-lighting', 125000, 119000, 98000, 8, 1.55, '/assets/products/elgato-keylight-air2.jpg', 'Flattering, flicker-free illumination for video calls and streaming. The edge-lit design creates a soft, shadowless light that flatters your appearance, while WiFi control via Stream Deck or app lets you adjust brightness and color temperature instantly.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/elgato-keylight-air2.jpg', 112000, 4.7, 1, 'Elgato', 1, 1),

('hue-solo-lightstrip-5m', 'Philips Hue Solo Lightstrip 5m with Bluetooth & Matter', 'smart-lighting', 55000, 53900, 45000, 10, 0.35, '/assets/products/hue-solo-strip.jpg', 'The most affordable entry into the Hue ecosystem. This 5-meter lightstrip features 1,600 lumens of tunable white light, Bluetooth control without a hub, and Matter support for future-proof integration. Cuttable and extendable for custom installations.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/hue-solo-strip.jpg', 50500, 4.6, 1, 'Philips', 1, 1),

-- HIGH-PERFORMANCE NETWORKING (10 products)
('tp-link-deco-be85-mesh', 'TP-Link Deco BE85 WiFi 7 Mesh System 3-Pack with 10G Ports', 'networking', 850000, 829000, 720000, 5, 4.5, '/assets/products/tp-link-deco-be85.jpg', 'Blazing WiFi 7 mesh coverage for estates and large homes up to 9,000 sq ft. Each node features dual 10Gbps ports for multi-gig internet, 12 internal antennas, and AI-driven mesh that optimizes the connection path for every device in real-time.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/tp-link-deco-be85.jpg', 780000, 4.7, 1, 'TP-Link', 1, 1),

('ubiquiti-cloud-gateway-ultra', 'Ubiquiti UniFi Cloud Gateway Ultra with 2.5GbE & 512GB SSD', 'networking', 250000, 245000, 215000, 6, 0.85, '/assets/products/unifi-gateway-ultra.jpg', 'A complete UniFi network controller, security gateway, and NVR in one compact appliance. With a 2.5GbE WAN port, integrated 512GB SSD for Protect camera storage, and support for 30+ UniFi devices, it''s the perfect brain for a sophisticated home network.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/unifi-gateway-ultra.jpg', 235000, 4.7, 1, 'Ubiquiti', 1, 1),

('asus-zenwifi-bq16-pro', 'ASUS ZenWiFi BQ16 Pro WiFi 7 Mesh Router 2-Pack - White', 'networking', 650000, 639000, 555000, 4, 2.8, '/assets/products/asus-zenwifi-bq16.jpg', 'Cover up to 6,000 sq ft with quad-band WiFi 7 featuring a dedicated 6GHz backhaul that prevents mesh slowdown. ASUS AiProtection Pro with lifetime security updates, VPN Fusion, and a 2.5GbE WAN port make this the discerning homeowner''s choice.', 1, unixepoch('2026-06-16'), 1, 555000, '/assets/products/asus-zenwifi-bq16.jpg', 605000, 4.6, 0, 'ASUS', 1, 1),

('netgear-nighthawk-rs700s', 'Netgear Nighthawk RS700S Tri-Band WiFi 7 Gaming Router', 'networking', 580000, 569000, 495000, 4, 1.65, '/assets/products/netgear-rs700s.jpg', 'Dominate online gaming with a router built for speed. The RS700S features a powerful quad-core processor, a dedicated gaming band, and DumaOS 4.0 with geo-filtering that connects you to the lowest-latency game servers. 10GbE WAN future-proofs your connection.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/netgear-rs700s.jpg', 535000, 4.6, 0, 'Netgear', 1, 1),

('glinet-marble-beryl-ax', 'GL.iNet Beryl AX WiFi 6 Travel Router with OpenWrt & WireGuard', 'networking', 45000, 43900, 36500, 18, 0.22, '/assets/products/glinet-beryl-ax.jpg', 'Your secure travel companion that creates a private network from any hotel WiFi. Pre-installed WireGuard and OpenVPN with one-click connection, OpenWrt-based with extensive plugin support, and a USB port for file sharing or cellular modem tethering.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/glinet-beryl-ax.jpg', 41500, 4.5, 1, 'GL.iNet', 1, 1),

('tp-link-omada-eap783', 'TP-Link Omada EAP783 WiFi 7 Ceiling Access Point with 10G Uplink', 'networking', 320000, 315000, 268000, 6, 0.95, '/assets/products/tp-link-eap783.jpg', 'Enterprise-grade WiFi 7 for business and high-density environments. This ceiling-mounted AP supports 500+ concurrent clients with a 10Gbps PoE uplink, OFDMA, and seamless roaming through the Omada SDN platform. Ideal for offices, hotels, and conference centers.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/tp-link-eap783.jpg', 298000, 4.6, 0, 'TP-Link', 1, 1),

('firewalla-gold-se', 'Firewalla Gold SE 2.5GbE Cyber Security Firewall & Router', 'networking', 320000, 315000, 268000, 4, 0.85, '/assets/products/firewalla-gold-se.jpg', 'Protect every device on your network with enterprise-grade security in a box. Firewalla monitors traffic with deep packet inspection, blocks malware and phishing, enforces parental controls, and provides detailed network analytics through an intuitive phone app.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/firewalla-gold-se.jpg', 298000, 4.7, 0, 'Firewalla', 1, 1),

('mikrotik-crs310-8g-2s-in', 'MikroTik CRS310-8G+2S+IN 10-Port 2.5GbE Smart Switch with SFP+', 'networking', 165000, 159000, 132000, 6, 0.85, '/assets/products/mikrotik-crs310.jpg', 'Upgrade your home network to multi-gig speeds with eight 2.5GbE ports and two 10Gbps SFP+ cages. The Marvell switch chip powers wire-speed switching, while RouterOS Level 5 provides VLAN, LACP, and port isolation capabilities for advanced network segmentation.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/mikrotik-crs310.jpg', 149000, 4.6, 0, 'MikroTik', 1, 1),

('ubiquiti-unifi-flex-mini-2-5g', 'Ubiquiti UniFi Flex Mini 2.5G 5-Port Managed Switch with PoE', 'networking', 65000, 63900, 52000, 10, 0.22, '/assets/products/unifi-flex-mini-2.5g.jpg', 'A tiny, managed 2.5GbE switch that''s powered by PoE and fits in the palm of your hand. Five 2.5Gbps ports with VLAN support and UniFi controller integration provide enterprise management for multi-gig devices at an entry-level price.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/unifi-flex-mini-2.5g.jpg', 59000, 4.7, 1, 'Ubiquiti', 1, 1),

('cable-matters-10gbe-usb-c-adapter', 'Cable Matters 10GbE USB-C to RJ45 Ethernet Adapter with 100W PD', 'networking', 38000, 36900, 30500, 15, 0.08, '/assets/products/cablematters-10gbe.jpg', 'Add lightning-fast 10-gigabit wired networking to any USB-C laptop. This adapter passes through 100W of charging power so you don''t sacrifice your charging port, while the aluminum housing dissipates heat for sustained high-speed data transfers.', 1, unixepoch('2026-06-16'), 1, 30500, '/assets/products/cablematters-10gbe.jpg', 34800, 4.6, 1, 'Cable Matters', 1, 1);
